import { oneOf } from './one-of';
/**
 * Helper to create a multivariate experiment configuration
 */
export function createMultivariateExperiment(config) {
  const {
    values
  } = config;
  return {
    ...config,
    values: [...values],
    // Maintains the tuple
    typeGuard: oneOf(config.values),
    defaultValue: config.defaultValue
  };
}